// ── The Remembering — shared math, noise and palette ─────────────────────────
export const TILE = 28;
export const GRID = 96;
export const WORLD = TILE * GRID;
export const DAY_SECONDS = 300;

export const BIOME = {
  WATER: 0, SAND: 1, MEADOW: 2, FOREST: 3, MARSH: 4, ROCK: 5, ASH: 6,
};

export const BIOME_INFO = {
  [BIOME.WATER]:  { key: 'water',  name: 'water',  color: '#1b3d48', walk: false },
  [BIOME.SAND]:   { key: 'sand',   name: 'shore',  color: '#b9a374', walk: true },
  [BIOME.MEADOW]: { key: 'meadow', name: 'meadow', color: '#6d8450', walk: true },
  [BIOME.FOREST]: { key: 'forest', name: 'forest', color: '#405b3c', walk: true },
  [BIOME.MARSH]:  { key: 'marsh',  name: 'marsh',  color: '#4a5c46', walk: true },
  [BIOME.ROCK]:   { key: 'rock',   name: 'stone',  color: '#68665f', walk: true },
  [BIOME.ASH]:    { key: 'ash',    name: 'ashland',color: '#514944', walk: true },
};

export const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
export const lerp = (a, b, t) => a + (b - a) * t;
export const dist = (ax, ay, bx, by) => Math.hypot(bx - ax, by - ay);
export const dist2 = (ax, ay, bx, by) => (bx - ax) ** 2 + (by - ay) ** 2;
export const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
export const angleLerp = (a, b, t) => {
  let d = ((b - a + Math.PI) % (Math.PI * 2)) - Math.PI;
  if (d < -Math.PI) d += Math.PI * 2;
  return a + d * t;
};

export function hashString(str) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

export function seedLabel(seed) {
  return (seed >>> 0).toString(36).toUpperCase().padStart(6, '0').slice(-6);
}

export class RNG {
  constructor(seed) {
    this.s = (seed >>> 0) || 0x9e3779b9;
  }
  next() {
    this.s = (this.s + 0x6d2b79f5) | 0;
    let t = this.s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }
  range(a, b) { return a + this.next() * (b - a); }
  int(a, b) { return Math.floor(this.range(a, b + 1)); }
  pick(arr) { return arr[Math.floor(this.next() * arr.length)]; }
  chance(p) { return this.next() < p; }
  shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(this.next() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }
}

function hash2(ix, iy, seed) {
  let h = Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(seed, 1442695041);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}

export function noise2(x, y, seed) {
  const x0 = Math.floor(x), y0 = Math.floor(y);
  const fx = x - x0, fy = y - y0;
  const ux = fx * fx * (3 - 2 * fx);
  const uy = fy * fy * (3 - 2 * fy);
  const a = hash2(x0, y0, seed);
  const b = hash2(x0 + 1, y0, seed);
  const c = hash2(x0, y0 + 1, seed);
  const d = hash2(x0 + 1, y0 + 1, seed);
  return lerp(lerp(a, b, ux), lerp(c, d, ux), uy);
}

export function fbm(x, y, seed, octaves = 4) {
  let v = 0, amp = 0.5, freq = 1, norm = 0;
  for (let i = 0; i < octaves; i++) {
    v += noise2(x * freq, y * freq, seed + i * 1013) * amp;
    norm += amp;
    amp *= 0.5;
    freq *= 2.03;
  }
  return v / norm;
}

export function shade(hex, amount) {
  const n = parseInt(hex.slice(1), 16);
  let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  if (amount >= 0) {
    r = Math.round(lerp(r, 255, amount));
    g = Math.round(lerp(g, 255, amount));
    b = Math.round(lerp(b, 255, amount));
  } else {
    const t = 1 + amount;
    r = Math.round(r * t); g = Math.round(g * t); b = Math.round(b * t);
  }
  return `rgb(${r},${g},${b})`;
}

export function rgba(hex, alpha) {
  const n = parseInt(hex.slice(1), 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${alpha})`;
}

export function formatClock(fraction) {
  const total = Math.floor(((fraction % 1) + 1) % 1 * 24 * 60);
  const h = Math.floor(total / 60), m = total % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

export function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

export function angleDiff(a, b) {
  let d = ((b - a + Math.PI) % (Math.PI * 2)) - Math.PI;
  if (d < -Math.PI) d += Math.PI * 2;
  return d;
}

export function inArc(px, py, cx, cy, facing, radius, arc) {
  const d = Math.hypot(px - cx, py - cy);
  if (d > radius) return false;
  const a = Math.atan2(py - cy, px - cx);
  return Math.abs(angleDiff(facing, a)) <= arc / 2;
}

export function pickName(rng, used = new Set()) {
  const first = ['Wren','Kestrel','Mara','Ash','Rowan','Sable','Orin','Maelin','Iris','Bram','Fenn','Tove','Rook','Lark','Cael','Nyla','Dain','Eira','Sorrel','Vale'];
  const last = ['of the Fen','the Quiet','Ashborn','of Greywatch','the Kind','Halfhand','of the Long Road','the Watchful','Emberwise','of Hollow Pines','the Unbroken','Duskward'];
  for (let i = 0; i < 30; i++) {
    const n = `${rng.pick(first)} ${rng.pick(last)}`;
    if (!used.has(n)) { used.add(n); return n; }
  }
  return `Wanderer ${Math.floor(rng.range(10, 99))}`;
}

export const TACTIC_LABELS = {
  rangedKills: 'ranged kills',
  meleeKills: 'close kills',
  stealthKills: 'unseen kills',
  trapKills: 'snare kills',
  fireHits: 'fire wounds',
  escapes: 'escaped foes',
};

// ── The Remembering — procedural valley ──────────────────────────────────────
import {
  TILE, GRID, WORLD, BIOME, BIOME_INFO, RNG, fbm, clamp, dist,
} from './util.js';

const NAME_BANK = {
  [BIOME.FOREST]: [
    ['Hollow', 'Mosslight', 'Briar', 'Rook', 'Fallow', 'Thorn'],
    ['Pines', 'Wood', 'Thicket', 'Reach', 'Holt', 'Canopy'],
  ],
  [BIOME.MARSH]: [
    ['Drowned', 'Willow', 'Fen', 'Reed', 'Mire', 'Grey'],
    ['Fen', 'Marsh', 'Mire', 'Crossing', 'Water', 'Hollow'],
  ],
  [BIOME.ROCK]: [
    ['Grey', 'Stone', 'Rook', 'Iron', 'High', 'Bare'],
    ['Watch', 'Crag', 'Rise', 'Spine', 'Shelf', 'Gate'],
  ],
  [BIOME.ASH]: [
    ['Cinder', 'Ashen', 'Ember', 'Soot', 'Char', 'Black'],
    ['Steppe', 'Vale', 'Waste', 'Reach', 'Field', 'Hollow'],
  ],
  [BIOME.MEADOW]: [
    ['Amber', 'Fallow', 'Long', 'Sweet', 'Golden', 'Quiet'],
    ['Meadow', 'Reach', 'Crossing', 'Grass', 'Downs', 'Field'],
  ],
  [BIOME.SAND]: [
    ['Pale', 'Salt', 'Shell', 'Wrack', 'Dune', 'Low'],
    ['Shore', 'Strand', 'Bank', 'Beach', 'Cove', 'Point'],
  ],
};

const RESOURCE_RULES = {
  [BIOME.FOREST]: [['tree', 0.20], ['bush', 0.035], ['fiber', 0.05], ['rock', 0.008]],
  [BIOME.MEADOW]: [['tree', 0.018], ['bush', 0.045], ['fiber', 0.05], ['berry', 0.022], ['rock', 0.012]],
  [BIOME.MARSH]:  [['reed', 0.16], ['bush', 0.025], ['fiber', 0.035], ['tree', 0.02]],
  [BIOME.ROCK]:   [['rock', 0.14], ['tree', 0.014], ['fiber', 0.012]],
  [BIOME.ASH]:    [['rock', 0.07], ['deadtree', 0.035], ['fiber', 0.01]],
  [BIOME.SAND]:   [['reed', 0.018], ['rock', 0.01], ['driftwood', 0.012]],
};

export class World {
  constructor(seed) {
    this.seed = seed >>> 0;
    this.rng = new RNG(this.seed);
    this.tiles = new Uint8Array(GRID * GRID);
    this.heights = new Float32Array(GRID * GRID);
    this.moisture = new Float32Array(GRID * GRID);
    this.regions = [];
    this.pois = [];
    this.settlements = [];
    this.resources = [];
    this.explored = new Uint8Array(48 * 48);
    this.spawn = { x: WORLD / 2, y: WORLD / 2 };
    this.generateTerrain();
    this.generateRegions();
    this.placeWorld();
    this.spawnResources();
    this.ensureTutorialResources();
    this.pickSpawn();
  }

  generateTerrain() {
    for (let gy = 0; gy < GRID; gy++) {
      for (let gx = 0; gx < GRID; gx++) {
        const nx = (gx + 0.5) / GRID;
        const ny = (gy + 0.5) / GRID;
        const d = Math.hypot(nx - 0.5, ny - 0.5) * 1.48;
        let h = fbm(nx * 2.7 + 11.3, ny * 2.7 + 4.7, this.seed, 5);
        h = h * 0.94 + 0.17 - d * d * 0.72;
        h += (fbm(nx * 8.1 + 30, ny * 8.1 + 70, this.seed ^ 0x5bd1, 3) - 0.5) * 0.055;
        const m = fbm(nx * 3.2 + 47.1, ny * 3.2 + 91.7, this.seed ^ 0x9e3779b9, 3);
        this.heights[gy * GRID + gx] = h;
        this.moisture[gy * GRID + gx] = m;
        let biome;
        if (h < 0.385) biome = BIOME.WATER;
        else if (h < 0.412) biome = BIOME.SAND;
        else if (h > 0.735) biome = BIOME.ROCK;
        else if (m > 0.635) biome = BIOME.MARSH;
        else if (h > 0.625 && m < 0.405) biome = BIOME.ASH;
        else if (m > 0.485) biome = BIOME.FOREST;
        else biome = BIOME.MEADOW;
        this.tiles[gy * GRID + gx] = biome;
      }
    }
  }

  generateRegions() {
    const used = new Set();
    for (let ry = 0; ry < 3; ry++) {
      for (let rx = 0; rx < 3; rx++) {
        const id = ry * 3 + rx;
        const counts = {};
        const x0 = Math.floor(rx * GRID / 3), x1 = Math.floor((rx + 1) * GRID / 3);
        const y0 = Math.floor(ry * GRID / 3), y1 = Math.floor((ry + 1) * GRID / 3);
        for (let gy = y0; gy < y1; gy++) {
          for (let gx = x0; gx < x1; gx++) {
            const b = this.tiles[gy * GRID + gx];
            if (b !== BIOME.WATER) counts[b] = (counts[b] || 0) + 1;
          }
        }
        let dominant = BIOME.MEADOW;
        let best = -1;
        for (const [k, v] of Object.entries(counts)) {
          if (v > best) { best = v; dominant = Number(k); }
        }
        const bank = NAME_BANK[dominant] || NAME_BANK[BIOME.MEADOW];
        let name = '';
        for (let i = 0; i < 24; i++) {
          const candidate = `${this.rng.pick(bank[0])} ${this.rng.pick(bank[1])}`;
          if (!used.has(candidate)) { name = candidate; used.add(candidate); break; }
        }
        if (!name) name = `Unnamed ${id + 1}`;
        this.regions.push({
          id, name, dominant,
          rect: { x0: x0 * TILE, y0: y0 * TILE, x1: x1 * TILE, y1: y1 * TILE },
          states: [], heat: 0, discovered: false,
        });
      }
    }
  }

  placeWorld() {
    const settlementNames = ['Hearthcamp', 'Fenwick', 'Ashwatch'];
    const settlementRegions = [4, 0, 8];
    settlementRegions.forEach((regionId, i) => {
      const poi = this.placePOI('settlement', regionId, settlementNames[i], 420, true);
      if (!poi) return;
      const roles = i === 0
        ? ['Keeper', 'Trader', 'Hunter']
        : i === 1 ? ['Elder', 'Trader', 'Warden'] : ['Warden', 'Trader', 'Hunter'];
      const names = i === 0
        ? ['Maelin', 'Sable', 'Orin']
        : i === 1 ? ['Tove', 'Bram', 'Iris'] : ['Rook', 'Lark', 'Dain'];
      poi.npcSpots = roles.map((role, j) => {
        const a = (j / roles.length) * Math.PI * 2 + this.rng.range(-0.4, 0.4);
        const r = this.rng.range(34, 58);
        return { role, name: names[j], x: poi.x + Math.cos(a) * r, y: poi.y + Math.sin(a) * r };
      });
      poi.tents = [];
      for (let j = 0; j < 3; j++) {
        const a = (j / 3) * Math.PI * 2 + 0.7;
        poi.tents.push({ x: poi.x + Math.cos(a) * 78, y: poi.y + Math.sin(a) * 78, rot: a + Math.PI / 2, hue: j });
      }
      poi.fire = { x: poi.x, y: poi.y };
      poi.radius = 108;
      this.settlements.push(poi);
    });

    const ruinNames = ['The Sunken Chapel', 'Old Greywatch', 'Bone Circle'];
    [2, 6, 7].forEach((regionId, i) => {
      const poi = this.placePOI('ruin', regionId, ruinNames[i], 340, false);
      if (!poi) return;
      poi.walls = [];
      const n = 5 + Math.floor(this.rng.range(0, 3));
      for (let j = 0; j < n; j++) {
        const a = (j / n) * Math.PI * 2;
        poi.walls.push({
          x: poi.x + Math.cos(a) * this.rng.range(36, 62),
          y: poi.y + Math.sin(a) * this.rng.range(30, 52),
          w: this.rng.range(24, 52), h: this.rng.range(13, 20),
          rot: a + this.rng.range(-0.4, 0.4),
        });
      }
      poi.chest = { x: poi.x + this.rng.range(-18, 18), y: poi.y + this.rng.range(10, 30) };
      poi.radius = 90;
    });

    const shrineNames = ['Shrine of the Quiet', 'The Ember Shrine'];
    [1, 5].forEach((regionId, i) => {
      const poi = this.placePOI('shrine', regionId, shrineNames[i], 320, false);
      if (!poi) return;
      poi.stones = [];
      for (let j = 0; j < 5; j++) {
        const a = (j / 5) * Math.PI * 2 + 0.2;
        poi.stones.push({
          x: poi.x + Math.cos(a) * 40, y: poi.y + Math.sin(a) * 34,
          h: this.rng.range(28, 46), w: this.rng.range(9, 14), rot: this.rng.range(-0.2, 0.2),
        });
      }
      poi.radius = 70;
    });

    [3, 7].forEach((regionId, i) => {
      const poi = this.placePOI('camp', regionId, i === 0 ? "Hunter's Rest" : 'Drifter Camp', 280, false);
      if (!poi) return;
      poi.radius = 58;
      poi.npcSpots = [{
        role: i === 0 ? 'Hunter' : 'Drifter',
        name: i === 0 ? 'Fenn' : 'Sorrel',
        x: poi.x + 20, y: poi.y + 12,
      }];
      poi.tents = [{ x: poi.x - 24, y: poi.y - 12, rot: 0.5, hue: 2 }];
      poi.fire = { x: poi.x + 10, y: poi.y - 6 };
    });
  }

  placePOI(type, regionId, name, minSpacing, needsOpen) {
    const region = this.regions[regionId];
    const target = { x: (region.rect.x0 + region.rect.x1) / 2, y: (region.rect.y0 + region.rect.y1) / 2 };
    let best = null, bestScore = -1;
    for (let attempt = 0; attempt < 120; attempt++) {
      const x = attempt === 0 ? target.x : region.rect.x0 + this.rng.range(0.14, 0.86) * (region.rect.x1 - region.rect.x0);
      const y = attempt === 0 ? target.y : region.rect.y0 + this.rng.range(0.14, 0.86) * (region.rect.y1 - region.rect.y0);
      if (!this.isLand(x, y)) continue;
      if (needsOpen && this.landFraction(x, y, 5) < 0.74) continue;
      if (this.pois.some(p => dist(p.x, p.y, x, y) < minSpacing)) continue;
      let score = this.landFraction(x, y, 4) + this.rng.range(0, 0.18);
      if (x < 200 || y < 200 || x > WORLD - 200 || y > WORLD - 200) score -= 0.5;
      if (score > bestScore) { bestScore = score; best = { x, y }; }
      if (attempt > 70 && best) break;
    }
    if (!best) {
      for (let i = 0; i < 500; i++) {
        const x = this.rng.range(180, WORLD - 180), y = this.rng.range(180, WORLD - 180);
        if (this.isLand(x, y) && this.landFraction(x, y, 4) > 0.7 &&
            !this.pois.some(p => dist(p.x, p.y, x, y) < minSpacing)) { best = { x, y }; break; }
      }
    }
    if (!best) return null;
    const poi = { id: this.pois.length, type, name, x: best.x, y: best.y, region: regionId };
    this.pois.push(poi);
    return poi;
  }

  spawnResources() {
    const rng = this.rng;
    for (let gy = 1; gy < GRID - 1; gy++) {
      for (let gx = 1; gx < GRID - 1; gx++) {
        const biome = this.tiles[gy * GRID + gx];
        const rules = RESOURCE_RULES[biome];
        if (!rules) continue;
        const x = (gx + rng.range(0.2, 0.8)) * TILE;
        const y = (gy + rng.range(0.2, 0.8)) * TILE;
        if (this.pois.some(p => dist(p.x, p.y, x, y) < (p.type === 'settlement' ? 128 : 68))) continue;
        for (const [kind, chance] of rules) {
          if (!rng.chance(chance)) continue;
          this.addResource(kind, x, y, rng);
          break;
        }
      }
    }
  }

  addResource(kind, x, y, rng = this.rng) {
    const base = {
      kind: 'resource', type: kind, x, y,
      r: kind === 'tree' || kind === 'deadtree' ? 13 : kind === 'rock' ? 15 : 10,
      variant: rng.int(0, 3), phase: rng.range(0, Math.PI * 2),
      hp: kind === 'tree' ? 3 : kind === 'rock' ? 3 : 1,
      maxHp: kind === 'tree' ? 3 : kind === 'rock' ? 3 : 1,
      sway: rng.range(0.7, 1.4),
    };
    if (kind === 'tree') base.pine = rng.chance(0.62);
    if (kind === 'berry') base.ripe = true;
    this.resources.push(base);
    return base;
  }

  ensureTutorialResources() {
    const hearth = this.settlements[0];
    if (!hearth) return;
    const rng = this.rng;
    const counts = { tree: 0, rock: 0, berry: 0 };
    for (let i = 0; i < 24; i++) {
      const a = rng.range(0, Math.PI * 2);
      const r = rng.range(120, 235);
      const x = hearth.x + Math.cos(a) * r;
      const y = hearth.y + Math.sin(a) * r;
      if (!this.isLand(x, y)) continue;
      const type = i % 4 === 0 ? 'rock' : i % 5 === 0 ? 'berry' : 'tree';
      if (counts[type] >= (type === 'tree' ? 8 : 4)) continue;
      if (this.resources.some(n => dist(n.x, n.y, x, y) < 44)) continue;
      this.addResource(type, x, y, rng);
      counts[type]++;
    }
  }

  pickSpawn() {
    const hearth = this.settlements[0];
    if (!hearth) {
      this.spawn = { x: WORLD / 2, y: WORLD / 2 };
      return;
    }
    for (let i = 0; i < 120; i++) {
      const a = this.rng.range(0, Math.PI * 2);
      const r = this.rng.range(95, 145);
      const x = hearth.x + Math.cos(a) * r;
      const y = hearth.y + Math.sin(a) * r;
      if (this.canWalk(x, y, 12)) { this.spawn = { x, y }; return; }
    }
    this.spawn = { x: hearth.x, y: hearth.y + 100 };
  }

  // ── queries ────────────────────────────────────────────────────────────────
  tileIndex(x, y) {
    const gx = clamp(Math.floor(x / TILE), 0, GRID - 1);
    const gy = clamp(Math.floor(y / TILE), 0, GRID - 1);
    return gy * GRID + gx;
  }
  biomeAt(x, y) { return this.tiles[this.tileIndex(x, y)]; }
  isWater(x, y) { return this.biomeAt(x, y) === BIOME.WATER; }
  isLand(x, y) { return !this.isWater(x, y); }
  isNearWater(x, y, range = 80) {
    for (let a = 0; a < Math.PI * 2; a += Math.PI / 6) {
      for (let r = 20; r <= range; r += 20) {
        if (this.isWater(x + Math.cos(a) * r, y + Math.sin(a) * r)) return true;
      }
    }
    return false;
  }
  canWalk(x, y, r = 10) {
    if (x < r || y < r || x > WORLD - r || y > WORLD - r) return false;
    if (this.isWater(x, y)) return false;
    if (this.isWater(x + r * 0.7, y) || this.isWater(x - r * 0.7, y)) return false;
    if (this.isWater(x, y + r * 0.7) || this.isWater(x, y - r * 0.7)) return false;
    return true;
  }
  landFraction(x, y, tiles) {
    let land = 0, total = 0;
    const gx = Math.floor(x / TILE), gy = Math.floor(y / TILE);
    for (let oy = -tiles; oy <= tiles; oy++) {
      for (let ox = -tiles; ox <= tiles; ox++) {
        const tx = gx + ox, ty = gy + oy;
        if (tx < 0 || ty < 0 || tx >= GRID || ty >= GRID) continue;
        total++;
        if (this.tiles[ty * GRID + tx] !== BIOME.WATER) land++;
      }
    }
    return total ? land / total : 0;
  }
  regionAt(x, y) {
    const rx = clamp(Math.floor(x / WORLD * 3), 0, 2);
    const ry = clamp(Math.floor(y / WORLD * 3), 0, 2);
    return this.regions[ry * 3 + rx];
  }
  poiAt(x, y, range = 120) {
    return this.pois.find(p => dist(p.x, p.y, x, y) < (p.radius || 90) + range) || null;
  }
  addRegionState(regionId, state) {
    const region = this.regions[regionId];
    if (region && !region.states.includes(state)) region.states.push(state);
  }
  reveal(x, y, radiusTiles = 9) {
    const cx = Math.floor(x / TILE / 2), cy = Math.floor(y / TILE / 2);
    const r = Math.ceil(radiusTiles / 2);
    for (let oy = -r; oy <= r; oy++) {
      for (let ox = -r; ox <= r; ox++) {
        const tx = cx + ox, ty = cy + oy;
        if (tx < 0 || ty < 0 || tx >= 48 || ty >= 48) continue;
        if (ox * ox + oy * oy <= r * r) this.explored[ty * 48 + tx] = 1;
      }
    }
  }
  biomeName(x, y) { return BIOME_INFO[this.biomeAt(x, y)].name; }
}

// ── The Remembering — persistent memory, reputation and adaptation ───────────
import { clamp, RNG } from './util.js';

export const DOCTRINES = {
  shieldwall: {
    id: 'shieldwall', name: 'Shieldwall', stat: 'rangedKills', threshold: 2,
    desc: 'The Hollow raise hide shields. Arrows glance from their guard.',
    rumor: 'They carry shields now. Word of your arrows reached them.',
    icon: '◒',
  },
  slipstep: {
    id: 'slipstep', name: 'Slipstep', stat: 'meleeKills', threshold: 3,
    desc: 'They have learned to slip the first blow and circle behind it.',
    rumor: 'They no longer stand still when you swing. They have learned your rhythm.',
    icon: '↝',
  },
  sappers: {
    id: 'sappers', name: 'Sappers', stat: 'trapKills', threshold: 1,
    desc: 'Hollow sappers disarm snares before the line walks into them.',
    rumor: 'They send sappers ahead now. Your little wire tricks will not hold them.',
    icon: '⌁',
  },
  wardens: {
    id: 'wardens', name: 'Lantern Wardens', stat: 'stealthKills', threshold: 2,
    desc: 'Lantern sentries watch the dark. Crouching no longer hides you from them.',
    rumor: 'Lanterns move through the pines at night. They are looking for the quiet one.',
    icon: '◉',
  },
  hounds: {
    id: 'hounds', name: 'Scent Hounds', stat: 'escapes', threshold: 3,
    desc: 'Ash hounds follow your trail long after you break line of sight.',
    rumor: 'You ran. They bred hounds for runners. They will find the trail you left.',
    icon: '⌇',
  },
  ashwalkers: {
    id: 'ashwalkers', name: 'Ashwalkers', stat: 'fireHits', threshold: 2,
    desc: 'Ashwalkers have learned to walk through flame. Fire wounds them less.',
    rumor: 'They walk through fire now. Someone taught them not to fear your torch.',
    icon: '△',
  },
};

const CAUSES = {
  hollow: 'the Hollow', wolf: 'ash wolves', bear: 'a cave bear',
  starvation: 'hunger', thirst: 'thirst', cold: 'the cold', fall: 'the valley',
};

export class MemorySystem {
  constructor(seed) {
    this.seed = seed >>> 0;
    this.reset();
  }

  reset() {
    this.entries = [];
    this.stats = {
      rangedKills: 0, meleeKills: 0, stealthKills: 0, trapKills: 0,
      fireHits: 0, escapes: 0, kills: 0, hunts: 0, gifts: 0, thefts: 0,
      crafts: 0, shrines: 0, nights: 0, distance: 0,
    };
    this.doctrines = {};
    for (const id of Object.keys(DOCTRINES)) {
      this.doctrines[id] = { progress: 0, unlocked: false };
    }
    this.rep = {};
    this.regions = {};
    this.dead = [];
    this.legend = 0;
    this.day = 1;
    this.time = 0.3;
    this.characterName = '';
    this.seq = 0;
    this.lastRumor = -1;
  }

  ensureRegion(id) {
    if (!this.regions[id]) this.regions[id] = { states: [], heat: 0, visits: 0 };
    return this.regions[id];
  }

  record({ type = 'deed', text, region = null, tags = [], weight = 1, witnesses = [] }) {
    const entry = {
      id: ++this.seq,
      day: this.day,
      time: this.time,
      type,
      text,
      region,
      tags,
      weight,
      witnesses,
    };
    this.entries.push(entry);
    if (this.entries.length > 140) this.entries.splice(0, this.entries.length - 140);
    this.legend = Math.min(999, this.legend + weight);
    return entry;
  }

  increment(stat, amount = 1) {
    if (this.stats[stat] === undefined) this.stats[stat] = 0;
    this.stats[stat] += amount;
    const unlocked = [];
    for (const doc of Object.values(DOCTRINES)) {
      if (doc.stat !== stat) continue;
      const state = this.doctrines[doc.id];
      if (state.unlocked) continue;
      state.progress = Math.min(doc.threshold, state.progress + amount);
      if (state.progress >= doc.threshold) {
        state.unlocked = true;
        unlocked.push(doc);
      }
    }
    return unlocked;
  }

  isUnlocked(id) { return !!this.doctrines[id]?.unlocked; }
  progressOf(id) {
    const doc = DOCTRINES[id];
    const state = this.doctrines[id];
    return { value: state.progress, max: doc.threshold, unlocked: state.unlocked };
  }

  reputation(place) { return this.rep[place] || 0; }
  changeRep(place, delta) {
    this.rep[place] = clamp((this.rep[place] || 0) + delta, -100, 100);
    return this.rep[place];
  }

  addRegionState(regionId, state) {
    const r = this.ensureRegion(regionId);
    if (!r.states.includes(state)) r.states.push(state);
  }
  regionStates(regionId) { return this.ensureRegion(regionId).states; }
  addHeat(regionId, amount) {
    const r = this.ensureRegion(regionId);
    r.heat = clamp(r.heat + amount, 0, 100);
  }
  heat(regionId) { return this.ensureRegion(regionId).heat; }
  decayHeat(dt) {
    for (const r of Object.values(this.regions)) {
      r.heat = Math.max(0, r.heat - dt * 0.16);
    }
  }

  recent(n = 8) { return this.entries.slice(-n).reverse(); }
  inRegion(regionName, n = 5) {
    return this.entries.filter(e => e.region === regionName).slice(-n).reverse();
  }
  topMemories(n = 5) {
    return [...this.entries].sort((a, b) => b.weight - a.weight).slice(0, n);
  }
  doctrineList() {
    return Object.values(DOCTRINES).map(doc => ({ ...doc, ...this.doctrines[doc.id] }));
  }
  unlockedDoctrines() {
    return Object.values(DOCTRINES).filter(doc => this.doctrines[doc.id].unlocked);
  }
  topTactic() {
    const pairs = Object.entries(this.stats)
      .filter(([k]) => ['rangedKills', 'meleeKills', 'stealthKills', 'trapKills', 'fireHits', 'escapes'].includes(k))
      .sort((a, b) => b[1] - a[1]);
    return pairs[0]?.[1] > 0 ? pairs[0][0] : null;
  }

  rumor(game, npc) {
    const rng = new RNG((this.seed ^ (npc.id * 7919) ^ (this.seq * 31)) >>> 0);
    const region = game.world.regions[npc.region];
    const place = region?.name || 'the valley';
    const local = this.inRegion(place, 6);
    const unlocked = this.unlockedDoctrines();
    const options = [];

    if (local.length) {
      const entry = rng.pick(local);
      options.push(`They say you ${stripYou(entry.text)}. The ${npc.role === 'Trader' ? 'road' : 'fires'} still talk about it.`);
    }
    if (unlocked.length) {
      options.push(rng.pick(unlocked).rumor);
    }
    if (this.dead.length) {
      const last = this.dead[this.dead.length - 1];
      options.push(`You walk like ${last.name}. The valley still tells stories about what happened on day ${last.day}.`);
    }
    if (this.reputation(place) >= 15) {
      options.push(`Hearthcamp has been kind to you. That kindness travels farther than you think.`);
    } else if (this.reputation(place) <= -15) {
      options.push(`There are names for people like you. I will not use them at my fire.`);
    }
    if (this.regionStates(region?.id)?.includes('scorched')) {
      options.push(`This land was green before the fire. The Hollow remember who lit it.`);
    }
    if (this.regionStates(region?.id)?.includes('hunted-out')) {
      options.push(`The deer are gone from ${place}. Something has been hunting too hard.`);
    }
    const generic = [
      `The Hollow are not one enemy. They are a memory with spears.`,
      `At night, watch the treeline. They send the ones who have learned your shape.`,
      `The valley keeps a ledger. Every kindness and every knife.`,
      `If you run, they will learn the sound of your running.`,
      `There is a shrine east of here. The stones listen better than I do.`,
      `Ashwatch has not answered a signal fire in three days.`,
    ];
    options.push(rng.pick(generic));
    let idx = Math.floor(rng.next() * options.length);
    if (options.length > 1 && idx === this.lastRumor) idx = (idx + 1) % options.length;
    this.lastRumor = idx;
    return options[idx];
  }

  epitaph() {
    const docs = this.unlockedDoctrines().length;
    if (this.legend > 80) return 'The valley will tell this story for a long time.';
    if (docs >= 4) return 'The Hollow will teach your tactics to the next one.';
    if (this.dead.length) return 'Another name for the ledger.';
    return 'The grass closes over the trail.';
  }

  serialize() {
    return {
      seed: this.seed, entries: this.entries, stats: this.stats, doctrines: this.doctrines,
      rep: this.rep, regions: this.regions, dead: this.dead, legend: this.legend,
      day: this.day, time: this.time, characterName: this.characterName, seq: this.seq,
    };
  }

  load(data) {
    if (!data) return;
    this.entries = data.entries || [];
    this.stats = { ...this.stats, ...(data.stats || {}) };
    this.doctrines = data.doctrines || this.doctrines;
    this.rep = data.rep || {};
    this.regions = data.regions || {};
    this.dead = data.dead || [];
    this.legend = data.legend || 0;
    this.day = data.day || 1;
    this.time = data.time ?? 0.3;
    this.characterName = data.characterName || '';
    this.seq = data.seq || this.entries.length;
    for (const id of Object.keys(DOCTRINES)) {
      if (!this.doctrines[id]) this.doctrines[id] = { progress: 0, unlocked: false };
    }
  }
}

function stripYou(text) {
  return text.replace(/^You /, '').replace(/^you /, '');
}

export function causeLabel(cause) {
  return CAUSES[cause] || 'the valley';
}

export function legendTier(legend) {
  return clamp(Math.floor(legend / 18), 0, 12);
}

