:root {
  --ink: #0a100e;
  --ink-2: #0f1814;
  --parchment: #e9dfc6;
  --parchment-dim: #b9ad92;
  --muted: #8d927f;
  --ember: #e08a4c;
  --ember-bright: #f2b26c;
  --moss: #8ba06b;
  --blood: #b14a3d;
  --line: rgba(233, 223, 198, 0.13);
  --line-strong: rgba(233, 223, 198, 0.24);
  --glass: rgba(11, 19, 15, 0.78);
  --glass-2: rgba(15, 25, 20, 0.9);
  --serif: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Palatino, Georgia, serif;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }
html, body {
  margin: 0; padding: 0; height: 100%; overflow: hidden;
  background: var(--ink); color: var(--parchment);
  font-family: var(--sans); font-size: 14px;
  -webkit-font-smoothing: antialiased;
  touch-action: none; user-select: none; -webkit-user-select: none;
  overscroll-behavior: none;
}
button, input { font-family: inherit; }
button { cursor: pointer; }
.hidden { display: none !important; }

#game {
  position: fixed; inset: 0; display: block;
  background: #10231f; cursor: crosshair;
}
body.panel-open #game { cursor: default; }

/* ── HUD shell ────────────────────────────────────────────────────────────── */
.hud {
  position: fixed; inset: 0; z-index: 10;
  pointer-events: none;
  padding: max(18px, env(safe-area-inset-top, 0px)) 22px calc(16px + var(--safe-b));
  transition: opacity .4s ease;
}
.hud.hidden { opacity: 0; display: block !important; pointer-events: none; }
.hud-top {
  display: grid; grid-template-columns: 1fr auto 1fr;
  align-items: start; gap: 16px;
}
.panel-soft {
  background: linear-gradient(160deg, rgba(16, 26, 21, 0.82), rgba(9, 15, 12, 0.72));
  border: 1px solid var(--line);
  border-radius: 12px;
  box-shadow: 0 10px 34px rgba(0, 0, 0, 0.28), inset 0 1px 0 rgba(255,255,255,0.04);
  backdrop-filter: blur(9px) saturate(0.9);
  -webkit-backdrop-filter: blur(9px) saturate(0.9);
  pointer-events: auto;
}

/* vitals */
.vitals { width: 218px; padding: 9px 11px 8px; display: flex; flex-direction: column; gap: 5px; }
.vital {
  display: grid; grid-template-columns: 15px 1fr 27px; align-items: center; gap: 7px;
  height: 17px; cursor: pointer;
}
.v-icon { font-size: 11px; color: var(--muted); text-align: center; line-height: 1; }
.v-track {
  height: 4px; background: rgba(0,0,0,0.42); border-radius: 4px; overflow: hidden;
  box-shadow: inset 0 1px 2px rgba(0,0,0,0.4);
}
.v-fill { height: 100%; width: 100%; border-radius: 4px; transition: width .25s ease; }
.vital[data-vital="hp"] .v-fill { background: linear-gradient(90deg, #8f3a33, #c06052); }
.vital[data-vital="stam"] .v-fill { background: linear-gradient(90deg, #9a7b43, #d4ac62); }
.vital[data-vital="hunger"] .v-fill { background: linear-gradient(90deg, #6f7a3f, #a6a75a); }
.vital[data-vital="thirst"] .v-fill { background: linear-gradient(90deg, #4c7680, #7fa9b0); }
.vital[data-vital="warmth"] .v-fill { background: linear-gradient(90deg, #8a5a36, #cc8a54); }
.vital[data-vital="hp"] .v-icon { color: #c77a6c; }
.vital[data-vital="stam"] .v-icon { color: #c8a660; }
.vital[data-vital="hunger"] .v-icon { color: #a9aa68; }
.vital[data-vital="thirst"] .v-icon { color: #86b0b7; }
.vital[data-vital="warmth"] .v-icon { color: #cc8a54; }
.v-val { font-size: 9px; color: var(--parchment-dim); text-align: right; font-variant-numeric: tabular-nums; }
.vital.low .v-fill { animation: lowPulse 1.1s ease-in-out infinite; }
.vital.low .v-val { color: #e4a07f; }
@keyframes lowPulse { 0%,100% { filter: brightness(1); } 50% { filter: brightness(1.7); } }

/* clock */
.world-clock { text-align: center; padding-top: 2px; text-shadow: 0 2px 12px rgba(0,0,0,0.8); }
.clock-line {
  font-family: var(--serif); font-size: 14px; letter-spacing: 0.12em;
  color: var(--parchment); display: flex; justify-content: center; gap: 8px; align-items: center;
}
.clock-line .dot { color: rgba(233,223,198,0.35); }
#weather-label { color: var(--parchment-dim); font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase; }
.region-line {
  margin-top: 4px; font-size: 9.5px; letter-spacing: 0.28em; text-transform: uppercase;
  color: rgba(233,223,198,0.6);
}
.hud.night .world-clock { color: #c8d4d1; }

/* top actions */
.top-actions { justify-self: end; display: flex; align-items: stretch; gap: 6px; pointer-events: auto; }
.memory-chip {
  display: flex; flex-direction: column; justify-content: center;
  min-width: 78px; padding: 6px 10px;
  background: linear-gradient(160deg, rgba(16, 26, 21, 0.85), rgba(9, 15, 12, 0.7));
  border: 1px solid var(--line); border-radius: 10px;
  line-height: 1;
}
.chip-label { font-size: 7.5px; letter-spacing: 0.22em; color: var(--muted); }
.memory-chip #memory-count { font-family: var(--serif); font-size: 18px; color: var(--ember-bright); margin-top: 2px; }
.chip-sub { font-size: 8px; color: var(--parchment-dim); margin-top: 2px; }
.icon-btn {
  width: 36px; min-width: 36px; border: 1px solid var(--line); border-radius: 10px;
  background: rgba(12, 20, 16, 0.75); color: var(--parchment-dim);
  font-size: 16px; display: grid; place-items: center;
  transition: .18s ease; backdrop-filter: blur(8px);
}
.icon-btn:hover { color: var(--parchment); border-color: var(--line-strong); background: rgba(27, 39, 31, 0.9); }
.icon-btn.muted { color: rgba(233,223,198,0.28); text-decoration: line-through; }

/* minimap */
#minimap-panel {
  position: absolute; right: 22px; top: 76px; width: 172px; padding: 7px;
  border-radius: 12px;
}
#minimap { display: block; width: 100%; height: auto; border-radius: 7px; filter: saturate(0.85) contrast(1.03); }
.minimap-caption {
  display: flex; justify-content: space-between; padding: 6px 2px 1px;
  font-size: 7.5px; letter-spacing: 0.2em; color: var(--muted); text-transform: uppercase;
}
#minimap-seed { color: rgba(233,223,198,0.4); }

/* quest */
#quest-card {
  position: absolute; left: 22px; top: 150px; width: 296px; padding: 14px 16px 13px;
  border-left: 2px solid rgba(224,138,76,0.65);
  background: linear-gradient(155deg, rgba(16,26,21,0.8), rgba(9,15,12,0.66));
}
.eyebrow {
  font-size: 8px; letter-spacing: 0.3em; text-transform: uppercase; color: var(--ember);
  font-weight: 600;
}
#quest-title {
  font-family: var(--serif); font-size: 16px; font-weight: 500; line-height: 1.25;
  margin: 7px 0 5px; color: var(--parchment);
}
#quest-text { font-size: 11px; line-height: 1.55; color: var(--parchment-dim); margin: 0; }
.quest-progress { margin-top: 8px; font-size: 9px; letter-spacing: 0.14em; color: var(--ember); min-height: 11px; }

/* toasts */
#toasts {
  position: absolute; left: 22px; bottom: 104px; display: flex; flex-direction: column-reverse;
  gap: 6px; max-width: 330px; pointer-events: none;
}
.toast {
  display: flex; gap: 9px; align-items: flex-start;
  background: rgba(10, 17, 13, 0.88); border: 1px solid var(--line);
  border-radius: 8px; padding: 8px 11px;
  font-size: 11px; line-height: 1.45; color: var(--parchment-dim);
  box-shadow: 0 8px 24px rgba(0,0,0,0.3);
  opacity: 0; transform: translateX(-10px); transition: .3s ease;
  backdrop-filter: blur(8px);
}
.toast.show { opacity: 1; transform: none; }
.toast-mark { width: 5px; height: 5px; border-radius: 50%; margin-top: 5px; background: var(--moss); flex: 0 0 5px; }
.toast.warn .toast-mark { background: var(--ember); }
.toast.danger .toast-mark { background: var(--blood); }
.toast.good .toast-mark { background: #9fbd7e; }
.toast.memory { border-color: rgba(224,138,76,0.3); }
.toast.memory .toast-mark { background: var(--ember-bright); box-shadow: 0 0 8px rgba(242,178,108,0.7); }

/* banner */
.banner {
  position: absolute; left: 50%; top: 17%; transform: translate(-50%, 8px);
  text-align: center; width: min(640px, 90vw); opacity: 0; pointer-events: none;
  transition: opacity .7s ease, transform .7s ease;
  text-shadow: 0 4px 28px rgba(0,0,0,0.9);
}
.banner.show { opacity: 1; transform: translate(-50%, 0); }
.banner-kicker { font-size: 9px; letter-spacing: 0.42em; color: var(--ember); text-transform: uppercase; margin-bottom: 8px; }
.banner-title { font-family: var(--serif); font-size: clamp(28px, 4vw, 44px); font-weight: 400; color: var(--parchment); letter-spacing: 0.01em; }
.banner-sub { font-size: 11px; letter-spacing: 0.06em; color: var(--parchment-dim); margin-top: 7px; }
.banner.danger .banner-kicker { color: #d57060; }
.banner.danger .banner-title { color: #e7c7b8; }
.banner.memory .banner-title { font-style: italic; color: var(--ember-bright); }

/* hotbar */
#hotbar {
  position: absolute; left: 50%; bottom: calc(16px + var(--safe-b)); transform: translateX(-50%);
  display: flex; gap: 6px; padding: 7px; border-radius: 14px; pointer-events: auto;
}
.slot {
  position: relative; width: 64px; height: 58px; border-radius: 9px;
  background: rgba(23, 33, 26, 0.6); border: 1px solid rgba(233,223,198,0.1);
  color: var(--parchment-dim); display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 1px; transition: .16s ease;
}
.slot:hover { background: rgba(35, 48, 38, 0.8); color: var(--parchment); }
.slot.active {
  border-color: rgba(224,138,76,0.8); background: rgba(55, 43, 27, 0.72);
  color: var(--ember-bright); box-shadow: 0 0 0 1px rgba(224,138,76,0.18), 0 6px 20px rgba(0,0,0,0.35);
  transform: translateY(-3px);
}
.slot.locked { opacity: 0.38; filter: grayscale(0.7); }
.slot.locked .slot-icon { opacity: 0.4; }
.slot-key { position: absolute; top: 3px; left: 5px; font-size: 7.5px; color: rgba(233,223,198,0.45); }
.slot-icon { width: 21px; height: 21px; display: grid; place-items: center; }
.slot-icon svg { width: 21px; height: 21px; }
.slot-name { font-size: 7px; letter-spacing: 0.12em; text-transform: uppercase; color: rgba(233,223,198,0.5); }
.slot-count { position: absolute; right: 5px; bottom: 4px; font-size: 9px; color: var(--ember-bright); font-variant-numeric: tabular-nums; }
.slot-lock {
  position: absolute; inset: 0; display: none; place-items: center;
  font-size: 7px; letter-spacing: 0.16em; text-transform: uppercase; color: rgba(233,223,198,0.55);
  background: rgba(5,8,6,0.35); border-radius: 9px;
}
.slot.locked .slot-lock { display: grid; }
.hotbar-hint {
  align-self: center; padding: 0 8px 0 4px; font-size: 8px; letter-spacing: 0.08em;
  color: rgba(233,223,198,0.32); white-space: nowrap;
}
.hotbar-hint span { color: rgba(233,223,198,0.55); }

/* controls + prompt */
#controls-hint {
  position: absolute; left: 24px; bottom: calc(16px + var(--safe-b));
  display: flex; gap: 10px; flex-wrap: wrap; max-width: 340px;
  font-size: 8.5px; color: rgba(233,223,198,0.32); letter-spacing: 0.04em;
}
#controls-hint b { color: rgba(233,223,198,0.55); font-weight: 600; }
#interact-prompt {
  position: absolute; left: 50%; bottom: calc(96px + var(--safe-b)); transform: translateX(-50%);
  background: rgba(9,15,12,0.9); border: 1px solid rgba(233,223,198,0.2);
  border-radius: 999px; padding: 7px 14px; font-size: 10.5px; letter-spacing: 0.05em;
  color: var(--parchment); box-shadow: 0 8px 26px rgba(0,0,0,0.4); pointer-events: none;
  display: flex; align-items: center; gap: 7px;
}
.key {
  display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px;
  border: 1px solid rgba(233,223,198,0.35); border-radius: 4px;
  font-size: 9px; color: var(--ember-bright); background: rgba(224,138,76,0.08);
}

/* ── touch ────────────────────────────────────────────────────────────────── */
#touch-controls { display: none; }
body.touch #touch-controls { display: block; }
body.touch #controls-hint, body.touch .hotbar-hint { display: none; }
body.touch #interact-prompt { bottom: calc(160px + var(--safe-b)); }
#joystick {
  position: absolute; left: calc(24px + var(--safe-l)); bottom: calc(26px + var(--safe-b));
  width: 116px; height: 116px; border-radius: 50%;
  border: 1px solid rgba(233,223,198,0.18);
  background: radial-gradient(circle, rgba(233,223,198,0.07), rgba(9,15,12,0.32));
  pointer-events: auto; touch-action: none;
}
#joystick::after {
  content: ''; position: absolute; inset: 24px; border-radius: 50%;
  border: 1px dashed rgba(233,223,198,0.1);
}
#joystick-knob {
  position: absolute; left: 50%; top: 50%; width: 46px; height: 46px;
  margin: -23px 0 0 -23px; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(233,223,198,0.35), rgba(224,138,76,0.22));
  border: 1px solid rgba(233,223,198,0.28);
  transition: transform .08s linear;
}
.touch-actions {
  position: absolute; right: calc(22px + var(--safe-r)); bottom: calc(24px + var(--safe-b));
  display: grid; grid-template-columns: repeat(3, 54px); grid-template-rows: repeat(2, 54px);
  gap: 8px; pointer-events: auto;
}
.touch-btn {
  width: 54px; height: 54px; border-radius: 50%;
  border: 1px solid rgba(233,223,198,0.22); color: var(--parchment);
  background: rgba(13, 22, 17, 0.78); font-size: 17px;
  box-shadow: 0 4px 18px rgba(0,0,0,0.3); backdrop-filter: blur(8px);
}
.touch-btn:active { background: rgba(224,138,76,0.3); transform: scale(0.95); }
.touch-btn.small { width: 46px; height: 46px; font-size: 13px; justify-self: end; align-self: end; }
.touch-btn.attack { background: rgba(112, 48, 39, 0.8); border-color: rgba(196,100,84,0.45); font-size: 20px; }
.touch-btn.interact { background: rgba(92, 76, 44, 0.72); border-color: rgba(224,138,76,0.35); font-size: 14px; }

/* ── overlays ─────────────────────────────────────────────────────────────── */
.overlay {
  position: fixed; inset: 0; z-index: 40;
  display: flex; align-items: center; justify-content: center;
  opacity: 0; pointer-events: none; transition: opacity .35s ease;
  padding: 24px;
}
.overlay.open { opacity: 1; pointer-events: auto; }

/* title */
.title-screen {
  background:
    radial-gradient(ellipse at 50% 30%, rgba(21, 43, 33, 0.2), rgba(4, 8, 7, 0.82) 70%),
    linear-gradient(180deg, rgba(4,8,7,0.35), rgba(4,8,7,0.86));
  backdrop-filter: blur(3px) saturate(0.8);
  z-index: 60;
}
.title-bg {
  position: absolute; inset: 0; pointer-events: none;
  background:
    radial-gradient(circle at 50% 18%, rgba(224,138,76,0.10), transparent 34%),
    radial-gradient(circle at 16% 80%, rgba(90,120,90,0.08), transparent 30%);
}
.title-inner {
  position: relative; text-align: center; max-width: 760px; width: 100%;
  padding: 20px; animation: riseIn .9s ease both;
}
@keyframes riseIn { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
.title-eyebrow {
  font-size: 8.5px; letter-spacing: 0.44em; color: var(--ember);
  text-transform: uppercase; margin-bottom: 22px;
}
.title-main {
  font-family: var(--serif); font-weight: 400; margin: 0;
  font-size: clamp(48px, 9vw, 96px); line-height: 0.92; letter-spacing: -0.025em;
  color: var(--parchment); text-shadow: 0 10px 60px rgba(0,0,0,0.75);
}
.title-main em { font-style: italic; color: var(--ember-bright); }
.title-rule { display: flex; align-items: center; justify-content: center; gap: 14px; margin: 24px auto 18px; width: min(340px, 70%); }
.title-rule span { height: 1px; flex: 1; background: linear-gradient(90deg, transparent, rgba(233,223,198,0.3)); }
.title-rule span:last-child { background: linear-gradient(90deg, rgba(233,223,198,0.3), transparent); }
.title-rule i { font-style: normal; font-size: 9px; color: var(--ember); }
.title-tagline { font-family: var(--serif); font-size: clamp(17px, 2vw, 22px); font-style: italic; color: #d9cba9; margin: 0 0 12px; }
.title-blurb { font-size: 12px; line-height: 1.75; color: var(--parchment-dim); max-width: 520px; margin: 0 auto 24px; }
.seed-row {
  display: flex; align-items: center; justify-content: center; gap: 10px;
  margin: 0 auto 20px; flex-wrap: wrap;
}
.seed-row label { font-size: 8px; letter-spacing: 0.26em; text-transform: uppercase; color: var(--muted); }
#seed-input {
  width: 106px; padding: 7px 10px; text-align: center;
  background: rgba(9,15,12,0.7); border: 1px solid var(--line); border-radius: 6px;
  color: var(--parchment); font-size: 12px; letter-spacing: 0.18em; outline: none;
  text-transform: uppercase;
}
#seed-input:focus { border-color: rgba(224,138,76,0.5); }
.seed-hint { font-size: 8.5px; color: rgba(233,223,198,0.3); }
.title-actions { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; }
.btn {
  border: 1px solid var(--line-strong); background: rgba(18, 28, 22, 0.72);
  color: var(--parchment); border-radius: 7px; padding: 10px 18px;
  font-size: 10.5px; letter-spacing: 0.12em; text-transform: uppercase;
  transition: .18s ease; backdrop-filter: blur(6px);
}
.btn:hover { border-color: rgba(233,223,198,0.45); background: rgba(31, 44, 34, 0.85); transform: translateY(-1px); }
.btn.primary {
  background: linear-gradient(160deg, #c67b43, #a55d34); border-color: rgba(242,178,108,0.6);
  color: #1a120b; font-weight: 700; box-shadow: 0 8px 28px rgba(165,93,52,0.24);
}
.btn.primary:hover { background: linear-gradient(160deg, #df9254, #b96a3b); }
.btn.ghost { background: transparent; color: var(--parchment-dim); }
.btn.danger { border-color: rgba(177,74,61,0.4); color: #d59a8d; }
.btn.small { padding: 7px 12px; font-size: 9px; }
.btn:disabled { opacity: 0.35; cursor: not-allowed; transform: none; }
.title-note { font-size: 9px; letter-spacing: 0.1em; color: rgba(233,223,198,0.36); margin: 18px 0 0; }
.title-foot {
  display: flex; gap: 10px; justify-content: center; margin-top: 42px;
  font-size: 8px; letter-spacing: 0.16em; text-transform: uppercase; color: rgba(233,223,198,0.24);
}
.foot-sep { color: rgba(233,223,198,0.12); }

/* sheets */
.panel-overlay { background: radial-gradient(ellipse at 50% 40%, rgba(6,10,8,0.6), rgba(3,6,5,0.9)); backdrop-filter: blur(5px); z-index: 45; }
.sheet {
  width: min(640px, 94vw); max-height: 88vh; overflow: auto;
  background:
    linear-gradient(155deg, rgba(21, 30, 24, 0.98), rgba(10, 17, 13, 0.99)),
    radial-gradient(circle at 20% 0%, rgba(224,138,76,0.06), transparent 40%);
  border: 1px solid rgba(233,223,198,0.16); border-radius: 16px;
  box-shadow: 0 30px 100px rgba(0,0,0,0.65), inset 0 1px 0 rgba(255,255,255,0.04);
  padding: 24px 26px 18px; scrollbar-width: thin; scrollbar-color: rgba(233,223,198,0.2) transparent;
}
.sheet.wide { width: min(1080px, 95vw); }
.sheet::-webkit-scrollbar { width: 6px; }
.sheet::-webkit-scrollbar-thumb { background: rgba(233,223,198,0.18); border-radius: 4px; }
.sheet-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; padding-bottom: 16px; border-bottom: 1px solid var(--line); }
.sheet-head h2 { font-family: var(--serif); font-size: 27px; font-weight: 400; margin: 5px 0 0; color: var(--parchment); }
.sheet-foot {
  display: flex; justify-content: space-between; gap: 20px; margin-top: 18px; padding-top: 12px;
  border-top: 1px solid var(--line); font-size: 8px; letter-spacing: 0.12em;
  color: rgba(233,223,198,0.3); text-transform: uppercase;
}
.foot-quote { font-family: var(--serif); font-size: 10px; letter-spacing: 0; text-transform: none; font-style: italic; color: rgba(233,223,198,0.34); }

/* journal */
.journal-body { display: grid; grid-template-columns: 1.15fr 1fr; gap: 28px; padding-top: 18px; }
.journal-col section { margin-bottom: 22px; }
.journal-col h3 {
  font-family: var(--serif); font-weight: 400; font-size: 15px; margin: 0 0 10px;
  color: var(--parchment); display: flex; justify-content: space-between; align-items: baseline; gap: 12px;
}
.journal-col h3 span { font-family: var(--sans); font-size: 8px; letter-spacing: 0.14em; color: var(--muted); text-transform: uppercase; }
.timeline { list-style: none; margin: 0; padding: 0; max-height: 46vh; overflow: auto; padding-right: 6px; }
.journal-entry { padding: 9px 0 9px 13px; border-left: 1px solid rgba(233,223,198,0.13); position: relative; }
.journal-entry::before {
  content: ''; position: absolute; left: -3px; top: 13px; width: 5px; height: 5px;
  border-radius: 50%; background: rgba(233,223,198,0.32);
}
.journal-entry.memory::before, .journal-entry.adapt::before { background: var(--ember); box-shadow: 0 0 8px rgba(224,138,76,0.55); }
.journal-entry.kill::before { background: var(--blood); }
.entry-top { display: flex; justify-content: space-between; font-size: 7.5px; letter-spacing: 0.12em; text-transform: uppercase; color: rgba(233,223,198,0.34); }
.journal-entry p { font-size: 11.5px; line-height: 1.5; margin: 4px 0 2px; color: var(--parchment-dim); }
.journal-entry small { font-size: 8.5px; color: rgba(233,223,198,0.3); font-style: italic; }
.journal-empty { font-size: 11px; color: var(--muted); font-style: italic; padding: 8px 0; list-style: none; }
.doctrines { display: flex; flex-direction: column; gap: 8px; }
.doctrine { padding: 9px 10px; border: 1px solid var(--line); border-radius: 8px; background: rgba(0,0,0,0.15); }
.doctrine.unlocked { border-color: rgba(224,138,76,0.35); background: rgba(224,138,76,0.06); }
.doc-head { display: flex; align-items: center; gap: 7px; font-size: 10.5px; color: var(--parchment-dim); }
