316:     for (const t of game.traps) {
317:       if (t.dead) continue;
318:       ctx.save();
319:       ctx.translate(t.x, t.y);
320:       ctx.strokeStyle = t.arm > 0 ? 'rgba(216,200,160,0.6)' : 'rgba(190,174,138,0.9)';
321:       ctx.lineWidth = 1.2;
322:       ctx.beginPath();
323:       ctx.arc(0, 0, 10, 0, 6.29);
324:       ctx.stroke();
325:       ctx.beginPath();
326:       for (let i = 0; i < 6; i++) {
327:         const a = i / 6 * Math.PI * 2;
328:         ctx.moveTo(Math.cos(a) * 4, Math.sin(a) * 4);
329:         ctx.lineTo(Math.cos(a + 0.5) * 11, Math.sin(a + 0.5) * 11);
330:       }
331:       ctx.stroke();
332:       ctx.restore();
333:     }
334:     for (const c of game.corpses) {
335:       if (c.fade <= 0) continue;
336:       ctx.save();
337:       ctx.translate(c.x, c.y);
338:       ctx.rotate(c.face || 0);
339:       ctx.globalAlpha = c.fade * 0.75;
340:       ctx.fillStyle = c.kind === 'wolf' || c.kind === 'deer' || c.kind === 'boar' ? '#3b3430' : '#2e2b26';
341:       ctx.beginPath();
342:       ctx.ellipse(0, 0, c.kind === 'bear' ? 20 : 13, c.kind === 'bear' ? 13 : 8, 0, 0, 6.29);
343:       ctx.fill();
344:       ctx.fillStyle = 'rgba(85,44,38,0.5)';
345:       ctx.beginPath();
346:       ctx.ellipse(4, 3, 10, 5, 0.3, 0, 6.29);
347:       ctx.fill();
348:       ctx.restore();
349:     }
350:   }
351: 
352:   drawWorld(ctx, game) {
353:     const items = [];
354:     const pad = 120;
355:     const inView = (x, y) => x > this.camX - pad && x < this.camX + this.vw + pad &&
356:       y > this.camY - pad && y < this.camY + this.vh + pad;
357: 
358:     for (const r of game.world.resources) {
359:       if (inView(r.x, r.y)) items.push({ y: r.y, kind: 'resource', o: r });
360:     }
361:     for (const poi of game.world.pois) {
362:       if (!inView(poi.x, poi.y)) continue;
363:       if (poi.type === 'settlement' || poi.type === 'camp') {
364:         for (const t of poi.tents) items.push({ y: t.y, kind: 'tent', o: t });
365:         if (poi.fire) items.push({ y: poi.fire.y, kind: 'fire', o: poi.fire });
366:       }
367:       if (poi.type === 'ruin') {
368:         for (const w of poi.walls) items.push({ y: w.y, kind: 'wall', o: w });
369:         if (poi.chest) items.push({ y: poi.chest.y, kind: 'chest', o: poi.chest, poi });
370:       }
371:       if (poi.type === 'shrine') {
372:         for (const s of poi.stones) items.push({ y: s.y, kind: 'stone', o: s });
373:       }
374:     }
375:     for (const n of game.npcs) if (inView(n.x, n.y)) items.push({ y: n.y, kind: 'npc', o: n });
376:     for (const a of game.animals) if (inView(a.x, a.y)) items.push({ y: a.y, kind: 'animal', o: a });
377:     for (const e of game.enemies) if (inView(e.x, e.y)) items.push({ y: e.y, kind: 'enemy', o: e });
378:     if (inView(game.player.x, game.player.y)) items.push({ y: game.player.y, kind: 'player', o: game.player });
379:     items.sort((a, b) => a.y - b.y);
380: 
381:     for (const it of items) {
382:       const o = it.o;
383:       switch (it.kind) {
384:         case 'resource': this.drawResource(ctx, o, game); break;
385:         case 'tent': this.drawTent(ctx, o); break;
386:         case 'fire': this.drawFire(ctx, o, game); break;
387:         case 'wall': this.drawWall(ctx, o); break;
388:         case 'chest': this.drawChest(ctx, o, it.poi, game); break;
389:         case 'stone': this.drawShrineStone(ctx, o, game); break;
390:         case 'npc': this.drawNPC(ctx, o, game); break;
391:         case 'animal': this.drawAnimal(ctx, o, game); break;
392:         case 'enemy': this.drawEnemy(ctx, o, game); break;
393:         case 'player': this.drawPlayer(ctx, o, game); break;
394:       }
395:     }
396: 
397:     for (const pr of game.projectiles) {
398:       if (!inView(pr.x, pr.y)) continue;
399:       ctx.save();
400:       ctx.translate(pr.x, pr.y);
401:       ctx.rotate(pr.angle);
402:       ctx.strokeStyle = pr.from === 'player' ? '#ded2b2' : '#c5b18c';
403:       ctx.lineWidth = 1.5;
404:       ctx.beginPath();
405:       ctx.moveTo(-13, 0);
406:       ctx.lineTo(8, 0);
407:       ctx.stroke();
408:       ctx.fillStyle = pr.from === 'player' ? '#e8dfc8' : '#b7483a';
409:       ctx.beginPath();
410:       ctx.moveTo(9, 0);
411:       ctx.lineTo(3, -3);
412:       ctx.lineTo(3, 3);
413:       ctx.closePath();
414:       ctx.fill();
415:       if (pr.fire) {
416:         ctx.fillStyle = 'rgba(232,137,74,0.35)';
417:         ctx.beginPath();
418:         ctx.arc(-6, 0, 7, 0, 6.29);
419:         ctx.fill();
420:       }
421:       ctx.restore();
422:     }
423: 
424:     for (const p of game.particles) {
425:       if (!inView(p.x, p.y)) continue;
426:       const a = clamp(p.life / p.maxLife, 0, 1);
427:       ctx.globalAlpha = a;
428:       if (p.type === 'spark' || p.type === 'ember') {
429:         ctx.strokeStyle = p.color;
430:         ctx.lineWidth = p.size * 0.7;
431:         ctx.beginPath();
432:         ctx.moveTo(p.x, p.y);
433:         ctx.lineTo(p.x - p.vx * 0.018, p.y - p.vy * 0.018);
434:         ctx.stroke();
435:       } else {
436:         ctx.fillStyle = p.color;
437:         ctx.beginPath();
438:         ctx.arc(p.x, p.y, p.size * (0.6 + a * 0.6), 0, 6.29);
439:         ctx.fill();
440:       }
441:       ctx.globalAlpha = 1;
442:     }
443: 
444:     for (const f of game.floats) {
445:       const a = clamp(f.life / f.maxLife, 0, 1);
446:       ctx.globalAlpha = a;
447:       ctx.font = f.big ? '600 16px Georgia, serif' : '600 12px ui-sans-serif, system-ui';
448:       ctx.textAlign = 'center';
449:       ctx.fillStyle = 'rgba(0,0,0,0.45)';
450:       ctx.fillText(f.text, f.x + 1, f.y - (1 - a) * 24 + 1);
451:       ctx.fillStyle = f.color;
452:       ctx.fillText(f.text, f.x, f.y - (1 - a) * 24);
453:       ctx.globalAlpha = 1;
454:     }
455:   }
456: 
457:   // ── scenery ────────────────────────────────────────────────────────────────
458:   drawResource(ctx, r, game) {
459:     const t = this.time;
460:     if (r.hp <= 0) {
461:       if (r.type === 'tree' || r.type === 'deadtree') {
462:         ctx.fillStyle = 'rgba(20,24,18,0.25)';
463:         ctx.beginPath(); ctx.ellipse(r.x + 2, r.y + 4, 10, 4, 0, 0, 6.29); ctx.fill();
464:         ctx.fillStyle = '#5a4631';
465:         ctx.beginPath(); ctx.ellipse(r.x, r.y - 2, 6, 5, 0, 0, 6.29); ctx.fill();
466:       }
467:       return;
468:     }
469:     const region = game.world.regionAt(r.x, r.y);
470:     const scorched = region.states.includes('scorched');
471:     if (r.type === 'tree') this.drawTree(ctx, r, t, scorched);
472:     else if (r.type === 'deadtree') this.drawDeadTree(ctx, r, t, scorched);
473:     else if (r.type === 'rock') this.drawRock(ctx, r, game);
474:     else if (r.type === 'bush' || r.type === 'berry') this.drawBush(ctx, r, t, scorched);
475:     else if (r.type === 'reed') this.drawReed(ctx, r, t);
476:     else if (r.type === 'fiber') this.drawFiber(ctx, r, t);
477:     else if (r.type === 'driftwood') this.drawDriftwood(ctx, r, t);
478:   }
479: 
480:   drawTree(ctx, r, t, scorched) {
481:     const sway = Math.sin(t * r.sway + r.phase) * 1.5;
482:     ctx.fillStyle = 'rgba(16,24,18,0.28)';
483:     ctx.beginPath();
484:     ctx.ellipse(r.x + 3, r.y + 3, 18, 7, 0, 0, 6.29);
485:     ctx.fill();
486:     ctx.fillStyle = scorched ? '#2c2622' : '#5b4631';
487:     ctx.fillRect(r.x - 2.5, r.y - 12, 5, 14);
488:     const dark = scorched ? '#2a2622' : (r.pine ? '#2f4a36' : '#3e5c3d');
489:     const mid = scorched ? '#38302a' : (r.pine ? '#3d5b41' : '#52714a');
490:     const light = scorched ? '#443a31' : (r.pine ? '#56724c' : '#6e8a56');
491:     if (r.pine) {
492:       for (let i = 0; i < 3; i++) {
493:         const y = r.y - 13 - i * 12;
494:         const w = 20 - i * 4;
495:         ctx.fillStyle = i === 2 ? light : i === 1 ? mid : dark;
496:         ctx.beginPath();
497:         ctx.moveTo(r.x + sway * (i + 1) * 0.35, y - 22);
498:         ctx.lineTo(r.x - w, y + 6);
499:         ctx.lineTo(r.x + w, y + 6);
500:         ctx.closePath();
501:         ctx.fill();
502:       }
503:     } else {
504:       const blobs = [
505:         [-10, -25, 15], [9, -27, 14], [0, -37, 16], [0, -22, 17],
506:       ];
507:       ctx.fillStyle = dark;
508:       for (const [dx, dy, rr] of blobs) {
509:         ctx.beginPath();
510:         ctx.arc(r.x + dx + sway, r.y + dy, rr, 0, 6.29);
511:         ctx.fill();
512:       }
513:       ctx.fillStyle = mid;
514:       for (const [dx, dy, rr] of blobs) {
515:         ctx.beginPath();
516:         ctx.arc(r.x + dx - 3 + sway * 1.3, r.y + dy - 4, rr * 0.78, 0, 6.29);
517:         ctx.fill();
518:       }
519:       ctx.fillStyle = light;
520:       ctx.beginPath();
521:       ctx.arc(r.x - 7 + sway * 1.4, r.y - 36, 8, 0, 6.29);
522:       ctx.arc(r.x + 7 + sway * 1.2, r.y - 31, 6, 0, 6.29);
523:       ctx.fill();
524:     }
525:   }
526: 
527:   drawDeadTree(ctx, r, t, scorched) {
528:     const sway = Math.sin(t * 0.9 + r.phase) * 1.2;
529:     ctx.fillStyle = 'rgba(16,20,16,0.25)';
530:     ctx.beginPath(); ctx.ellipse(r.x + 2, r.y + 3, 12, 5, 0, 0, 6.29); ctx.fill();
531:     ctx.strokeStyle = scorched ? '#211d1a' : '#4b4034';
532:     ctx.lineWidth = 4;
533:     ctx.beginPath();
534:     ctx.moveTo(r.x, r.y);
535:     ctx.lineTo(r.x + sway, r.y - 30);
536:     ctx.stroke();
537:     ctx.lineWidth = 2;
538:     ctx.beginPath();
539:     ctx.moveTo(r.x + sway * 0.5, r.y - 18);
540:     ctx.lineTo(r.x - 11, r.y - 30);
541:     ctx.moveTo(r.x + sway * 0.7, r.y - 23);
542:     ctx.lineTo(r.x + 10, r.y - 36);
543:     ctx.stroke();
544:   }
545: 
546:   drawRock(ctx, r, game) {
547:     const variant = r.variant;
548:     ctx.fillStyle = 'rgba(18,22,18,0.24)';
549:     ctx.beginPath(); ctx.ellipse(r.x + 3, r.y + 4, 17, 7, 0, 0, 6.29); ctx.fill();
550:     const base = variant % 2 ? '#69675f' : '#75726a';
551:     const pts = variant === 0
552:       ? [[-15, 2], [-11, -10], [2, -14], [14, -6], [12, 5], [0, 8]]
553:       : variant === 1
554:         ? [[-14, 3], [-9, -13], [5, -16], [15, -4], [10, 6], [-2, 7]]
555:         : [[-16, 1], [-8, -9], [1, -16], [11, -9], [14, 2], [5, 8]];
556:     ctx.fillStyle = base;
557:     ctx.beginPath();
558:     pts.forEach(([dx, dy], i) => i ? ctx.lineTo(r.x + dx, r.y + dy) : ctx.moveTo(r.x + dx, r.y + dy));
559:     ctx.closePath();
560:     ctx.fill();
561:     ctx.fillStyle = 'rgba(190,187,174,0.30)';
562:     ctx.beginPath();
563:     ctx.moveTo(r.x - 8, r.y - 7);
564:     ctx.lineTo(r.x + 1, r.y - 13);
565:     ctx.lineTo(r.x + 8, r.y - 6);
566:     ctx.lineTo(r.x - 1, r.y - 2);
567:     ctx.closePath();
568:     ctx.fill();
569:     const b = game.world.biomeAt(r.x, r.y);
570:     if (b === BIOME.FOREST || b === BIOME.MARSH) {
571:       ctx.fillStyle = 'rgba(91,120,66,0.55)';
572:       ctx.beginPath(); ctx.ellipse(r.x - 6, r.y - 4, 6, 2.4, 0.3, 0, 6.29); ctx.fill();
573:     }
574:   }
575: 
576:   drawBush(ctx, r, t, scorched) {
577:     const sway = Math.sin(t * 1.1 + r.phase) * 1;
578:     ctx.fillStyle = 'rgba(16,22,16,0.22)';
579:     ctx.beginPath(); ctx.ellipse(r.x + 2, r.y + 2, 12, 4, 0, 0, 6.29); ctx.fill();
580:     const col = scorched ? '#3b332c' : '#4d6a3f';
581:     ctx.fillStyle = col;
582:     for (const [dx, dy, rr] of [[-6, -6, 7], [5, -8, 7], [0, -13, 7]]) {
583:       ctx.beginPath(); ctx.arc(r.x + dx + sway, r.y + dy, rr, 0, 6.29); ctx.fill();
584:     }
585:     ctx.fillStyle = scorched ? '#4a4036' : '#688a51';
586:     ctx.beginPath(); ctx.arc(r.x - 4 + sway, r.y - 9, 4.5, 0, 6.29); ctx.fill();
587:     if (r.type === 'berry' && r.ripe && !scorched) {
588:       ctx.fillStyle = '#a84f46';
589:       for (let i = 0; i < 4; i++) {
590:         ctx.beginPath();
591:         ctx.arc(r.x - 7 + i * 4.4 + sway, r.y - 10 + (i % 2) * 4, 1.7, 0, 6.29);
592:         ctx.fill();
593:       }
594:     }
595:   }
596: 
597:   drawReed(ctx, r, t) {
598:     const sway = Math.sin(t * 1.6 + r.phase) * 2.4;
599:     ctx.strokeStyle = '#7a835c';
600:     ctx.lineWidth = 1.3;
601:     for (let i = 0; i < 4; i++) {
602:       const dx = (i - 1.5) * 3.4;
603:       ctx.beginPath();
604:       ctx.moveTo(r.x + dx, r.y);
605:       ctx.quadraticCurveTo(r.x + dx + sway * 0.5, r.y - 12, r.x + dx + sway, r.y - 20 - i);
606:       ctx.stroke();
607:     }
608:     ctx.fillStyle = '#8b7c55';
609:     ctx.beginPath(); ctx.ellipse(r.x + sway, r.y - 21, 2.4, 5, 0.15, 0, 6.29); ctx.fill();
610:   }
611: 
612:   drawFiber(ctx, r, t) {
613:     const sway = Math.sin(t * 2 + r.phase) * 2;
614:     ctx.strokeStyle = '#83945d';
615:     ctx.lineWidth = 1;
616:     for (let i = 0; i < 5; i++) {
617:       const dx = (i - 2) * 2.6;
618:       ctx.beginPath();
619:       ctx.moveTo(r.x + dx, r.y);
620:       ctx.quadraticCurveTo(r.x + dx + sway, r.y - 7, r.x + dx + sway * 1.7, r.y - 13 - (i % 2) * 3);
621:       ctx.stroke();
622:     }
623:   }
624: 
625:   drawDriftwood(ctx, r, t) {
626:     ctx.save();
627:     ctx.translate(r.x, r.y);
628:     ctx.rotate(r.phase);
629:     ctx.strokeStyle = '#8a7b63';
630:     ctx.lineWidth = 3.2;
631:     ctx.lineCap = 'round';
632:     ctx.beginPath();
633:     ctx.moveTo(-11, 0);
634:     ctx.lineTo(9, 1);
635:     ctx.stroke();
636:     ctx.lineWidth = 1.6;
637:     ctx.beginPath();
638:     ctx.moveTo(1, 0);
639:     ctx.lineTo(5, -7);
640:     ctx.stroke();
641:     ctx.restore();
642:   }
643: 
644:   drawTent(ctx, t) {
645:     const colors = [['#77664d', '#5a4c3a'], ['#6c7059', '#50543f'], ['#7d604e', '#5c4638']];
646:     const [c1, c2] = colors[t.hue % colors.length];
647:     ctx.save();
648:     ctx.translate(t.x, t.y);
649:     ctx.rotate(t.rot);
650:     ctx.fillStyle = 'rgba(14,20,16,0.28)';
651:     ctx.beginPath(); ctx.ellipse(2, 7, 25, 8, 0, 0, 6.29); ctx.fill();
652:     ctx.fillStyle = c2;
653:     ctx.beginPath();
654:     ctx.moveTo(-22, 8);
655:     ctx.lineTo(0, -30);
656:     ctx.lineTo(23, 8);
657:     ctx.closePath();
658:     ctx.fill();
659:     ctx.fillStyle = c1;
660:     ctx.beginPath();
661:     ctx.moveTo(-22, 8);
662:     ctx.lineTo(0, -30);
663:     ctx.lineTo(2, 8);
664:     ctx.closePath();
665:     ctx.fill();
666:     ctx.fillStyle = 'rgba(20,18,16,0.75)';
667:     ctx.beginPath();
668:     ctx.moveTo(-5, 8);
669:     ctx.lineTo(0, -12);
670:     ctx.lineTo(6, 8);
671:     ctx.closePath();
672:     ctx.fill();
673:     ctx.strokeStyle = 'rgba(220,206,174,0.25)';
674:     ctx.lineWidth = 1;
675:     ctx.beginPath(); ctx.moveTo(0, -30); ctx.lineTo(0, 8); ctx.stroke();
676:     ctx.restore();
677:   }
678: 
679:   drawFire(ctx, f, game) {
680:     const t = this.time;
681:     ctx.fillStyle = 'rgba(18,18,14,0.28)';
682:     ctx.beginPath(); ctx.ellipse(f.x, f.y + 4, 18, 7, 0, 0, 6.29); ctx.fill();
683:     for (let i = 0; i < 7; i++) {
684:       const a = i / 7 * Math.PI * 2;
685:       ctx.fillStyle = i % 2 ? '#6d6a61' : '#5a584f';
686:       ctx.beginPath();
687:       ctx.arc(f.x + Math.cos(a) * 12, f.y + Math.sin(a) * 8 + 1, 3.2, 0, 6.29);
688:       ctx.fill();
689:     }
690:     ctx.strokeStyle = '#5b4631';
691:     ctx.lineWidth = 3;
692:     ctx.beginPath();
693:     ctx.moveTo(f.x - 8, f.y + 3); ctx.lineTo(f.x + 7, f.y - 3);
694:     ctx.moveTo(f.x - 6, f.y - 4); ctx.lineTo(f.x + 8, f.y + 4);
695:     ctx.stroke();
696:     for (let i = 0; i < 3; i++) {
697:       const h = 16 + Math.sin(t * 7 + i * 2) * 5;
698:       const sway = Math.sin(t * 4 + i) * 2;
699:       ctx.fillStyle = i === 0 ? 'rgba(224,112,54,0.9)' : i === 1 ? 'rgba(244,166,74,0.9)' : 'rgba(255,224,150,0.9)';
700:       ctx.beginPath();
701:       ctx.moveTo(f.x - 6 + i * 3, f.y);
702:       ctx.quadraticCurveTo(f.x - 2 + sway, f.y - h * 0.55, f.x + sway * 1.3, f.y - h);
703:       ctx.quadraticCurveTo(f.x + 5 + sway, f.y - h * 0.45, f.x + 6 - i * 2, f.y);
704:       ctx.closePath();
705:       ctx.fill();
706:     }
707:   }
708: 
709:   drawWall(ctx, w) {
710:     ctx.save();
711:     ctx.translate(w.x, w.y);
712:     ctx.rotate(w.rot);
713:     ctx.fillStyle = 'rgba(16,20,17,0.24)';
714:     ctx.beginPath(); ctx.ellipse(2, 4, w.w / 2 + 3, 7, 0, 0, 6.29); ctx.fill();
715:     ctx.fillStyle = '#5f5d55';
716:     roundRect(ctx, -w.w / 2, -w.h, w.w, w.h + 5, 3);
717:     ctx.fill();
718:     ctx.fillStyle = '#757169';
719:     roundRect(ctx, -w.w / 2 + 2, -w.h + 1, w.w - 4, 4, 2);
720:     ctx.fill();
721:     ctx.strokeStyle = 'rgba(38,38,34,0.55)';
722:     ctx.lineWidth = 1;
723:     for (let i = -1; i <= 1; i++) {
724:       ctx.beginPath();
725:       ctx.moveTo(i * w.w / 3, -w.h + 5);
726:       ctx.lineTo(i * w.w / 3 + 2, 3);
727:       ctx.stroke();
728:     }
729:     ctx.fillStyle = 'rgba(88,112,64,0.4)';
730:     ctx.beginPath(); ctx.ellipse(-w.w / 3, -2, 7, 2.5, 0.2, 0, 6.29); ctx.fill();
731:     ctx.restore();
732:   }
733: 
734:   drawChest(ctx, c, poi, game) {
735:     const open = game.openedChests?.has(poi.id);
736:     ctx.save();
737:     ctx.translate(c.x, c.y);
738:     ctx.fillStyle = 'rgba(16,20,17,0.3)';
739:     ctx.beginPath(); ctx.ellipse(1, 3, 13, 5, 0, 0, 6.29); ctx.fill();
740:     ctx.fillStyle = '#5b4530';
741:     roundRect(ctx, -10, -8, 20, 13, 2);
742:     ctx.fill();
743:     ctx.fillStyle = open ? '#3b3026' : '#7a5c3a';
744:     roundRect(ctx, -10, -12, 20, 7, 2);
745:     ctx.fill();
746:     ctx.fillStyle = '#b08a4f';
747:     ctx.fillRect(-2, -7, 4, 6);
748:     ctx.restore();
749:   }
750: 
751:   drawShrineStone(ctx, s, game) {
752:     const glow = 0.55 + Math.sin(this.time * 2 + s.rot * 4) * 0.18;
753:     ctx.save();
754:     ctx.translate(s.x, s.y);
755:     ctx.rotate(s.rot);
756:     ctx.fillStyle = 'rgba(16,22,18,0.26)';
757:     ctx.beginPath(); ctx.ellipse(2, 3, s.w + 4, 5, 0, 0, 6.29); ctx.fill();
758:     ctx.fillStyle = '#676b60';
759:     roundRect(ctx, -s.w / 2, -s.h, s.w, s.h, 3);
760:     ctx.fill();
