1152:   // ── lighting and weather ───────────────────────────────────────────────────
1153:   drawLighting(game, camX, camY, night) {
1154:     if (night < 0.015) return;
1155:     const ctx = this.ctx;
1156:     const lc = this.lightCtx;
1157:     lc.clearRect(0, 0, this.vw, this.vh);
1158:     lc.globalCompositeOperation = 'source-over';
1159:     const dark = 0.82 * night;
1160:     const grad = lc.createLinearGradient(0, 0, 0, this.vh);
1161:     grad.addColorStop(0, `rgba(5,9,20,${dark * 1.04})`);
1162:     grad.addColorStop(1, `rgba(4,7,16,${dark * 0.92})`);
1163:     lc.fillStyle = grad;
1164:     lc.fillRect(0, 0, this.vw, this.vh);
1165:     lc.globalCompositeOperation = 'destination-out';
1166: 
1167:     const light = (wx, wy, radius, strength = 1) => {
1168:       const x = wx - camX, y = wy - camY;
1169:       if (x < -radius || y < -radius || x > this.vw + radius || y > this.vh + radius) return;
1170:       const g = lc.createRadialGradient(x, y, 2, x, y, radius);
1171:       g.addColorStop(0, `rgba(0,0,0,${0.95 * strength})`);
1172:       g.addColorStop(0.55, `rgba(0,0,0,${0.62 * strength})`);
1173:       g.addColorStop(1, 'rgba(0,0,0,0)');
1174:       lc.fillStyle = g;
1175:       lc.beginPath();
1176:       lc.arc(x, y, radius, 0, 6.29);
1177:       lc.fill();
1178:     };
1179: 
1180:     const p = game.player;
1181:     light(p.x, p.y, p.tool === 2 ? 155 : 105, 0.9);
1182:     for (const s of game.world.settlements) {
1183:       if (s.fire) light(s.fire.x, s.fire.y, 175, 1);
1184:     }
1185:     for (const poi of game.world.pois) {
1186:       if (poi.fire) light(poi.fire.x, poi.fire.y, 140, 0.9);
1187:       if (poi.type === 'shrine') light(poi.x, poi.y, 125, 0.65);
1188:     }
1189:     for (const e of game.enemies) {
1190:       if (!e.dead && e.lantern) light(e.x, e.y, 105, 0.8);
1191:     }
1192:     for (const pr of game.projectiles) {
